sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 root;
uniform float2 tip;
uniform float width;
uniform float sway;
uniform float speed;
uniform float phase;
uniform float strands;
uniform float anchor;
uniform float curl;

half4 main(float2 coord) {
    float2 a = root * size;
    float2 b = tip * size;
    float2 ab = b - a;
    float len2 = max(dot(ab, ab), 1.0);
    float t = clamp(dot(coord - a, ab) / len2, 0.0, 1.0);
    float2 p = a + ab * t;
    float2 perp = normalize(float2(-ab.y, ab.x) + float2(0.0001, 0.0));
    float across = dot(coord - p, perp);
    float w = width * min(size.x, size.y) * 0.5;
    float m = 1.0 - smoothstep(w * 0.55, w, abs(across));
    if (m <= 0.001) return image.eval(coord);
    float lock = mix(1.0, t, anchor);
    float grow = pow(t, 1.6) * lock;
    float wave = sin(time * speed * 6.2831853 + t * strands * 6.2831853 + phase * 6.2831853 + across * 0.02);
    float swing = wave * sway * min(size.x, size.y) * grow * m;
    float twist = sin(t * strands * 3.1415927 + phase * 6.2831853) * curl * min(size.x, size.y) * grow * m;
    float2 src = coord - perp * swing + normalize(ab) * twist * 0.35;
    return image.eval(src);
}
